package com.crypto.laplace.scheduler;
import static org.mockito.Mockito.*;import com.crypto.laplace.execution.LaplacePaperExecutionService;import com.crypto.laplace.persistence.LaplacePaperPositionRepository;import com.crypto.laplace.service.LaplacePositionManagementService;import com.crypto.laplace.session.LaplaceSessionManager;import org.junit.jupiter.api.Test;
class LaplaceStopLossSchedulerTest {@Test void delegatesCatchUpToSharedService(){var repo=mock(LaplacePaperPositionRepository.class);var management=mock(LaplacePositionManagementService.class);var execution=mock(LaplacePaperExecutionService.class);var session=mock(LaplaceSessionManager.class);new LaplaceStopLossScheduler(repo,management,execution,session).evaluate("position","BTCUSDT");verify(management).catchUp(eq("position"),any());verify(execution).drainTradeEvents();verify(session).tick();}@Test void scheduledEvaluationOnlyLoadsCurrentRun(){var repo=mock(LaplacePaperPositionRepository.class);var management=mock(LaplacePositionManagementService.class);var execution=mock(LaplacePaperExecutionService.class);var session=mock(LaplaceSessionManager.class);when(session.tradingRunId()).thenReturn("new-run");new LaplaceStopLossScheduler(repo,management,execution,session).evaluate();verify(repo).findByStrategyAndTradingRunIdAndStatus(LaplacePaperExecutionService.STRATEGY,"new-run",com.crypto.laplace.model.LaplacePositionStatus.OPEN);verifyNoInteractions(management);}}
